mapper.select:
select uc.id as id, uc.coupon_id as couponId, c.name as couponName, c.type as couponType, c.value as couponValue, c.min_amount as minAmount, c.start_time as startTime, c.end_time as endTime, uc.status as status, uc.use_time as useTime, uc.order_id as orderId, uc.create_time as createTime from user_coupon uc join coupon c on c.id = uc.coupon_id where uc.user_id = #{userId}
and uc.status = #{status}
order by uc.status asc, uc.id desc
